import {readFileSync} from "node:fs";

const read = (path) => JSON.parse(readFileSync(path, "utf8"));
const plan = read("shift-plan.json");
const night = read("night.json");
const capturePath = process.argv[2] ?? "operations/duty-2340.json";
const log = read(capturePath);

const limits = log.samples.map(
  (sample) => ((sample.acMeterEndKwh - sample.acMeterStartKwh) * 60) / sample.minutes,
);
const actual = limits.map((limit, slot) => Math.min(limit, plan.acKw[slot]));
const headroomKw = limits.map((limit, slot) => limit - plan.acKw[slot]);

const acEnergyByBus = {};
plan.bus.forEach((busId, slot) => {
  acEnergyByBus[busId] =
    (acEnergyByBus[busId] ?? 0) + actual[slot] * (log.samples[slot].minutes / 60);
});

const departureKwh = night.buses.map(
  (bus) => bus.startKwh + (acEnergyByBus[bus.id] ?? 0) * night.efficiency,
);
const marginsKwh = departureKwh.map(
  (energy, index) => energy - night.buses[index].requiredKwh,
);

console.log(
  JSON.stringify({
    run: log.run,
    time: log.time,
    capture: capturePath,
    limits,
    requested: plan.acKw,
    actual,
    headroomKw,
    withinLimits: plan.acKw.every((power, slot) => power <= limits[slot]),
    departureKwh,
    marginsKwh,
    dispatchAt85: plan.dispatchAt85,
  }),
);

